import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./braces-B2_rnCwm.js";import{C as n,D as r,E as i,M as a,N as o,O as s,P as c,T as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g}from"./shared-DoR5oW6-.js";import{t as _}from"./git-branch--KUP4I0u.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e(),b=`Этап 4 · Блок 13 · Организация и зрелые механизмы FastAPI`;function x({module:e}){return(0,y.jsxs)(o,{children:[(0,y.jsx)(a,{variant:`project`,chip:e??b,title:`63. Сервис через Depends`,intro:`HTTP-обработчики перестанут сами искать PlannerService в состоянии приложения. Мы вынесем получение уже собранного объекта в короткую функцию и подключим её к существующим маршрутам FastAPI.`,tags:[{icon:(0,y.jsx)(_,{size:14}),label:`provider`},{icon:(0,y.jsx)(t,{size:14}),label:`Depends(get_planner)`}]}),(0,y.jsxs)(c,{number:`00`,title:`От общей ссылки к аргументу обработчика`,children:[(0,y.jsx)(s,{children:`В прошлых занятиях приложение собрало PlannerService и сохранило его в app.state.planner. Task-обработчики читают эту ссылку через Request, а маршрут статистики обращается к тому же сервису из app.api. Теперь мы посмотрим, как передавать готовый объект параметру маршрута.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Сервис уже создан на границе запуска приложения; HTTP-код знает, где хранится ссылка на него.`},{title:`Новый вопрос`,description:`Как получить тот же PlannerService в обработчике, не повторяя request.app.state.planner в каждой операции?`},{title:`Результат`,description:`Обычная функция вернёт готовый объект, а Depends попросит FastAPI передать его параметру HTTP-обработчика.`}]}),(0,y.jsx)(`p`,{children:`Так знакомый путь от Request и app.state приводит к новому способу получения аргумента. Мы отделим чтение готовой ссылки от создания PlannerService, затем разберём, как FastAPI вызывает функцию и передаёт её результат обработчику.`})]}),(0,y.jsxs)(c,{number:`01`,title:`Получить готовый объект не значит создать новый`,children:[(0,y.jsx)(s,{children:`build_service собирает PlannerService вместе с хранилищем при запуске приложения. Ссылка на этот объект помещается в app.state.planner. Позже обработчик берёт ссылку и вызывает метод сервиса; повторное чтение ссылки само по себе не создаёт ни Planner, ни JsonStorage.`}),(0,y.jsx)(v,{caption:`фрагменты прежнего пути`,code:`# при сборке приложения
app.state.planner = build_service()

# внутри task-обработчика
planner = request.app.state.planner
return planner.select_tasks()`}),(0,y.jsx)(`p`,{children:`Представим общую библиотеку, где есть один экземпляр каталога. Запись в карточке указывает на этот каталог, а не содержит его копию. Когда несколько библиотекарей обращаются к той же карточке, они получают доступ к одному набору книг. В приложении роль карточки выполняет ссылка в app.state, а роль каталога - готовый PlannerService. Аналогия заканчивается на получении объекта: сервис ещё выполняет методы и меняет данные, библиотечная карточка этого не делает.`}),(0,y.jsx)(`p`,{children:`Provider нужен именно на границе выдачи ссылки. Если он каждый раз вызывает build_service или создаёт JsonStorage, то API может получить новый сервис с другой внутренней памятью. Такой код перестанет означать «возьми подготовленный Planner этого приложения». Для нашей задачи функция должна вернуть существующий объект из текущего Request, не выбирать путь к файлу и не открывать собственное хранилище.`}),(0,y.jsx)(m,{prompt:`Сопоставим части прежнего пути с их ролью.`,leftTitle:`Часть`,rightTitle:`Роль`,pairs:[{left:`build_service()`,right:`собирает сервис на границе запуска`},{left:`app.state.planner`,right:`хранит ссылку приложения на готовый объект`},{left:`метод PlannerService`,right:`выполняет операцию над задачами`},{left:`JsonStorage`,right:`сохраняет состояние Planner в JSON`}],explanation:`Мы разделили создание сервиса, хранение ссылки, предметную операцию и сохранение данных. Provider добавит единый способ получить сервис, но не заменит ни один из этих четырёх элементов.`}),(0,y.jsx)(i,{tone:`info`,children:`Сервис может создаваться один раз, хотя provider участвует в разрешении аргументов разных HTTP-запросов. Частота получения ссылки и время жизни объекта - разные вопросы.`})]}),(0,y.jsxs)(c,{number:`02`,title:`Provider остаётся обычной функцией`,children:[(0,y.jsx)(s,{children:`Provider - это функция приложения, которая возвращает объект, нужный следующему коду. Для FastAPI не требуется особый класс provider: важны её вход, возвращаемое значение и то, как endpoint объявляет источник аргумента.`}),(0,y.jsx)(u,{items:[{title:`Request`,description:`FastAPI передаёт функции текущий HTTP-запрос; через него доступно именно текущее приложение.`},{title:`Provider`,description:`Обычная функция читает подготовленное значение из app.state и возвращает его.`},{title:`Тип результата`,description:`Аннотация PlannerService объясняет ожидаемый объект и помогает читать сигнатуру; она не создаёт экземпляр.`}]}),(0,y.jsx)(`p`,{children:`Имя get_planner подсказывает действие, но Python не придаёт слову get специальный смысл. Функция становится provider по своей роли: её вызывают, чтобы получить значение для другой части программы. Она не обязана быть глобальной переменной и не должна импортировать созданный где-то ещё объект приложения. Через Request функция получает контекст текущего приложения, а значит может работать и с тестовой сборкой.`}),(0,y.jsx)(v,{caption:`завершённый независимый пример`,code:`def get_label() -> str:
    return "Палитра"

provider = get_label
value = get_label()

print(callable(provider))
print(value)`}),(0,y.jsx)(`p`,{children:`В строке provider = get_label мы передали функцию как значение: такой объект Python можно вызвать скобками, поэтому он называется вызываемым объектом (callable). Здесь скобок нет, значит вызова ещё не было. В строке value = get_label() мы вызвали функцию, поэтому в value попала строка. При запуске первый print показывает True, второй - Палитра. Это знакомое различие становится важным для Depends.`}),(0,y.jsx)(`p`,{children:`Представим пункт выдачи, где сотрудник может передать оператору номер ячейки или уже вынутую посылку. Callable - это передаваемая функция, то есть инструкция, как получить результат; вызов функции выполняет эту инструкцию и даёт результат. FastAPI получает callable provider, чтобы вызвать его в контексте запроса. Это сравнение не означает, что Python хранит функцию как текстовую инструкцию: функция остаётся объектом, который можно передать.`}),(0,y.jsx)(g,{code:`def get_palette(request: Request) -> Palette:
    return request.app.state.palette

@router.get("/palette")
def read_palette(palette: Palette = Depends(get_palette)):
    return {"name": palette.name}`,steps:[{line:4,note:`FastAPI видит callable get_palette в объявлении параметра и готовит его разрешение для запроса.`,vars:{provider:`get_palette`,call:`ещё не выполнен`}},{line:0,note:`При разборе запроса FastAPI вызывает provider и передаёт ему текущий Request.`,vars:{request:`текущее приложение`}},{line:1,note:`Функция читает уже сохранённую ссылку на Palette и возвращает тот же объект.`,vars:{result:`request.app.state.palette`}},{line:4,note:`FastAPI подставляет результат в аргумент palette и только затем вызывает endpoint.`,vars:{palette:`готовый объект`}},{line:5,note:`Обработчик использует полученный объект; он не отвечает за его создание.`,vars:{response:`имя палитры`}}]}),(0,y.jsx)(`p`,{children:`Мы проследили фрагмент приложения, где типы Palette, router и Request объявлены в другом месте; это не самостоятельный запускаемый файл и не запись реального запуска. Маршрут данных виден по шагам: передаваемая функция, запрос, ссылка из state, аргумент обработчика.`})]}),(0,y.jsxs)(c,{number:`03`,title:`Depends принимает функцию, а не её результат`,children:[(0,y.jsx)(s,{children:`В параметре endpoint простая запись выглядит как значение по умолчанию: palette: Palette = Depends(get_palette). Но FastAPI читает этот маркер при подключении маршрута и понимает, что значение нужно получить через функцию. Сам get_palette не вызывается в момент объявления обработчика.`}),(0,y.jsx)(`p`,{children:`Можно представить театральную постановку. В тексте роли указано, кто должен принести реквизит; запись не приносит его на сцену во время печати сценария. Перед выходом актёра координатор собирает нужные предметы и передаёт их исполнителю. Здесь сигнатура endpoint описывает источник аргумента, FastAPI координирует получение, а provider возвращает предметный объект. Граница аналогии в том, что FastAPI реально вызывает Python-функцию и проверяет её параметры, а координатор в театре не выполняет код.`}),(0,y.jsx)(v,{caption:`верная форма объявления`,code:`@router.get("/palette")
def read_palette(
    palette: Palette = Depends(get_palette),
):
    return {"name": palette.name}`}),(0,y.jsx)(`p`,{children:`Здесь get_palette без скобок остаётся callable. Выражение Depends(get_palette) сообщает FastAPI, как получить аргумент. При каждом запросе framework разрешает параметры зависимости в контексте приложения и передаёт возвращённый объект функции read_palette. Значение palette появляется уже при вызове endpoint, поэтому обычная Python-функция не должна подставлять его сама.`}),(0,y.jsx)(n,{code:`@router.get("/palette")
def read_palette(
    palette: Palette = Depends(get_palette()),
):
    return {"name": palette.name}`,question:`Найдём ошибку в момент передачи зависимости.`,options:[`Provider вызывается сразу, когда объявляется маршрут`,`Тип Palette запрещает FastAPI читать объект`,`HTTP-обработчик не может возвращать словарь`],correctIndex:0,explanation:`Вызов со скобками выполняет get_palette при построении аргумента, когда текущий Request ещё не передан. Depends должен получить функцию, чтобы FastAPI вызвал её позднее при разрешении запроса.`,fix:`Depends(get_palette)`}),(0,y.jsx)(l,{question:`Какой вариант сохраняет один подготовленный каталог для маршрутов?`,left:{title:`Создать заново`,code:`return Catalog.open("books.json")`,note:`Каждое разрешение создаёт новый объект и новый владелец состояния.`},right:{title:`Вернуть ссылку`,code:`return request.app.state.catalog`,note:`Provider получает объект, который уже собрала текущая сборка приложения.`},preferred:`right`,explanation:`Мы выбираем второй вариант только потому, что здесь договор требует общий уже подготовленный каталог. В других задачах создание объекта внутри функции может быть правильным; сначала определяем его время жизни и владельца.`}),(0,y.jsx)(`p`,{children:`Так же устроен планируемый get_planner: источник уже задан в state текущего приложения, а endpoint получает результат через Depends. Тип PlannerService помогает читать контракт, но ни аннотация, ни Depends не вызывают build_service и не создают новую JsonStorage.`})]}),(0,y.jsxs)(c,{number:`04`,title:`Один путь получения для task-операций и stats`,children:[(0,y.jsx)(s,{children:`После подготовки функции-provider мы можем заменить прямое чтение состояния в HTTP-обработчиках. Тело операции остаётся тем же: endpoint получает PlannerService, вызывает прежний метод, преобразует результат в прежний HTTP-ответ.`}),(0,y.jsx)(h,{caption:`Как FastAPI передаёт готовый Planner обработчику`,children:(0,y.jsxs)(p,{label:`Путь одного HTTP-запроса: от клиента через provider к обработчику`,children:[(0,y.jsx)(d,{title:`HTTP-запрос`,children:(0,y.jsx)(`p`,{children:`FastAPI начинает разбор аргументов маршрута`})}),(0,y.jsx)(f,{label:`разрешить Depends`}),(0,y.jsx)(d,{title:`get_planner`,children:(0,y.jsx)(`p`,{children:`Получает Request текущего приложения`})}),(0,y.jsx)(f,{label:`прочитать ссылку`}),(0,y.jsx)(d,{title:`app.state.planner`,children:(0,y.jsx)(`p`,{children:`Уже собранный PlannerService`})}),(0,y.jsx)(f,{label:`вернуть тот же объект`}),(0,y.jsx)(d,{title:`task-handler или stats`,children:(0,y.jsx)(`p`,{children:`Вызывает прежний метод сервиса`})})]})}),(0,y.jsx)(`p`,{children:`Текстовый маршрут схемы такой: запрос приводит FastAPI к параметру с Depends; framework вызывает get_planner с Request; provider читает ссылку из app.state и возвращает объект; endpoint получает его в параметре. Схема показывает последовательность получения значения, а не полный внутренний алгоритм FastAPI. Ответ клиенту формируется прежним обработчиком.`}),(0,y.jsx)(`p`,{children:`Task-router может использовать простую форму Depends(get_planner), а /stats получает тот же provider, хотя находится в app.api. Это убирает повторяющееся знание о месте хранения сервиса из бизнес-операций. Сам app.state остаётся частью сборки и источником ссылки; он не исчезает и не превращается в глобальный импорт для каждого router.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Параметр`,description:`Тип PlannerService говорит, какой объект будет доступен внутри обработчика.`},{title:`Источник`,description:`Depends(get_planner) просит FastAPI получить этот объект через provider.`},{title:`Операция`,description:`Тело endpoint продолжает вызывать прежний метод и сохраняет HTTP-контракт.`}]}),(0,y.jsx)(`p`,{children:`Это не новый CRUD-слой. Provider не принимает task_id, не проверяет title, не ловит TaskNotFoundError и не записывает JSON. Его работа заканчивается на выдаче сервиса. Если ошибка возникает в предметной операции или хранилище, её прежняя обработка остаётся на своих местах.`})]}),(0,y.jsxs)(c,{number:`05`,title:`FastAPI и CLI получают сервис разными путями`,children:[(0,y.jsx)(s,{children:`Depends относится к разрешению параметров FastAPI endpoint. CLI не отправляет HTTP-запрос, поэтому ему не нужны Request, Depends или искусственный вызов get_planner.`}),(0,y.jsx)(`p`,{children:`При запуске CLI остаётся прежний путь через build_service: команда получает PlannerService и вызывает его методы напрямую. В HTTP-пути FastAPI берёт уже подготовленную ссылку из текущего приложения через provider. Оба интерфейса могут пользоваться совместимыми операциями и одним настроенным JSON-файлом, хотя получают объект разными способами.`}),(0,y.jsx)(`p`,{children:`Такое разделение сохраняет границы слоёв. CLI не импортирует app или endpoint, provider не становится доменным сервисом, а PlannerService не начинает зависеть от FastAPI. Знакомый прямой вызов метода в тесте сервиса тоже не нуждается в Depends. Для HTTP-проверки тестовый клиент TestClient проходит через FastAPI и тем самым проверяет реальное разрешение аргумента.`}),(0,y.jsx)(i,{tone:`info`,children:`В этой задаче не нужны dependency_overrides, кэширование, yield и управление закрываемым ресурсом. Они решают другие вопросы и появятся только там, где маршрут блока их действительно вводит.`})]}),(0,y.jsxs)(c,{number:`06`,title:`Проверим общий объект и прежний контракт`,children:[(0,y.jsx)(s,{children:`Правильный provider должен вернуть именно сервис, установленный в изолированном тестовом приложении. Несколько запросов одного TestClient-сценария покажут, что созданная задача видна дальше, а stats и ответы CRUD остались прежними.`}),(0,y.jsx)(`p`,{children:`Тестовая fixture, то есть подготовительная функция проверки, создаёт сервис с временным JsonStorage, устанавливает его в app.state и после сценария восстанавливает прежнее состояние. Provider не должен обходить эту настройку или обращаться к рабочему JSON. Через последовательный HTTP-сценарий мы проверим создание и чтение, /stats, ожидаемый 404, PATCH с is_done=False и DELETE с пустым ответом 204.`}),(0,y.jsx)(`p`,{children:`Это проверяет два разных результата. Во-первых, provider возвращает объект из текущего приложения, а не из захардкоженного глобального app. Во-вторых, замена способа получения не меняет работу сервиса и HTTP-ответы. Проверка одного успешного GET не заметила бы случайно созданный второй Planner; связанный сценарий с повторным чтением и статистикой это обнаруживает.`}),(0,y.jsx)(`p`,{children:`Если fixture напрямую подменяет app.state.planner, это пока не dependency override. Мы проверяем известную точку состояния и то, что новый provider читает её. Отдельный механизм FastAPI для замены callable появится в другом шаге; смешивать два способа сейчас не нужно.`}),(0,y.jsx)(l,{question:`Что подтверждает цепочка POST → GET → stats на временном JSON?`,left:{title:`Только форму ответа`,code:`response.status_code == 200`,note:`Один статус не показывает, откуда endpoint получил сервис.`},right:{title:`Общий путь состояния`,code:`POST → GET → stats`,note:`Повторное чтение и статистика показывают, что запросы видят одну запись.`},preferred:`right`,explanation:`Мы проверяем связанный HTTP-результат и изолированное состояние. Пустой статусный чек может пройти даже при ошибочном источнике сервиса.`}),(0,y.jsx)(`p`,{children:`После изменений task-endpoints и /stats получают сервис через provider, а CLI продолжает работать через build_service. JSON, схема задачи, пути, коды ответов и обработчики ошибок остаются прежними. Если проверка выявила новый файл данных или отдельный Planner, сначала ищем ошибку границы получения, а не переписываем CRUD.`})]}),(0,y.jsxs)(c,{number:`07`,title:`Практика: подключим уже собранный Planner`,children:[(0,y.jsx)(s,{children:`В готовом проекте task-обработчики и /stats получают один собранный PlannerService через простую запись Depends. Мы сохраним прежние методы, HTTP-контракт и API-fixture с временным JSON.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Подключим источник`,description:`Provider вернёт PlannerService из текущего приложения; в HTTP-параметре окажется уже собранный объект.`},{title:`Переведём обработчики`,description:`Task-маршруты и /stats получат сервис через Depends, а их методы и ответы останутся прежними.`},{title:`Проверим поведение`,description:`Связанный сценарий на временном JSON подтвердит чтение созданной задачи, статистику, 404, PATCH false и DELETE 204.`}]}),(0,y.jsx)(`p`,{children:`Наблюдаемый итог: повторный запрос читает созданную задачу, а /stats видит то же состояние. Fixture оставляет данные в отдельном временном JSON и восстанавливает прежнюю ссылку на сервис после сценария.`}),(0,y.jsx)(`p`,{children:`Мы используем уже изученные Request, app.state, методы PlannerService и тестовый клиент. Изменение касается только получения сервиса в HTTP-слое: CLI по-прежнему собирает его через build_service, а правила CRUD, файл данных и публичные ответы не меняются.`}),(0,y.jsx)(r,{points:[(0,y.jsx)(y.Fragment,{children:`build_service создаёт PlannerService; provider возвращает уже готовый объект.`}),(0,y.jsx)(y.Fragment,{children:`Depends получает callable, а FastAPI подставляет результат в аргумент endpoint.`}),(0,y.jsx)(y.Fragment,{children:`Task-router и /stats используют единый HTTP-provider.`}),(0,y.jsx)(y.Fragment,{children:`CLI продолжает получать сервис через build_service.`}),(0,y.jsx)(y.Fragment,{children:`Тестовая fixture проверяет provider на временном JSON и восстанавливает состояние.`})]})]})]})}export{x as Lesson63};